package co.za.millenniumsolutions.repository;
import co.za.millenniumsolutions.model.AttendanceCapture; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository;
@Repository public class AttendanceCaptureRepository extends RepositorySupport { public AttendanceCaptureRepository(JdbcTemplate j){super(j);} public AttendanceCapture save(AttendanceCapture x){update("INSERT INTO attendance_capture(id,attendance_session_id,capture_type,captured_at,private_object_reference_id,location_valid,location_result) VALUES (?,?,?,COALESCE(?,CURRENT_TIMESTAMP),?,?,?) ON CONFLICT(id) DO UPDATE SET location_valid=excluded.location_valid,location_result=excluded.location_result",x.id(),x.attendanceSessionId(),x.captureType(),x.capturedAt()==null?null:x.capturedAt().toString(),x.privateObjectReferenceId(),x.locationValid()?1:0,x.locationResult()); return x;} }
